func main() {
    // Test cases
    testHeader := make(map[string]string)
    testHeader["Content-Type"] = "text/plain"

    updatedHeader1 := storeInfoInHeader("lang", "en-US", testHeader)
    fmt.Printf("%v\n", updatedHeader1)  // Should include Accept-Language: en-US

    updatedHeader2 := storeInfoInHeader("invalid", "test", testHeader)
